#!/usr/bin/env node
// Turns legal/terms.md and legal/privacy.md into a TypeScript module the app
// can bundle (Metro cannot import .md files). Run after editing either file:
//   node scripts/build-legal-content.mjs
// The markdown files are the source of truth; never edit the generated file.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

function parse(file) {
  const raw = readFileSync(join(root, "legal", file), "utf8");
  const match = raw.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
  if (!match) throw new Error(`${file}: missing front matter`);
  const meta = Object.fromEntries(
    match[1].split("\n").filter(Boolean).map((line) => {
      const i = line.indexOf(":");
      return [line.slice(0, i).trim(), line.slice(i + 1).trim().replace(/^"(.*)"$/, "$1")];
    }),
  );
  for (const key of ["title", "effective_date", "version"]) {
    if (!meta[key]) throw new Error(`${file}: front matter needs ${key}`);
  }
  return { title: meta.title, effectiveDate: meta.effective_date, version: meta.version, body: match[2].trim() };
}

const out = `// GENERATED by scripts/build-legal-content.mjs from legal/*.md. Do not edit.
export type LegalDocContent = { title: string; effectiveDate: string; version: string; body: string };

export const TERMS: LegalDocContent = ${JSON.stringify(parse("terms.md"), null, 2)};

export const PRIVACY: LegalDocContent = ${JSON.stringify(parse("privacy.md"), null, 2)};
`;
writeFileSync(join(root, "lib", "legal", "legal-docs.generated.ts"), out);
console.log("Wrote lib/legal/legal-docs.generated.ts");
